INSERT INTO org.organization VALUES(1,DEFAULT,'HOSP-DEMO','Образцовая больничная сеть — синтетический стенд','hospital',true);
INSERT INTO org.site(id,organization_id,code,name,address_text,location) SELECT g,1,'SITE-'||g,(ARRAY['Главный стационар','Амбулаторный центр','Диагностический центр'])[g],'Учебный адрес, корпус '||g,ext.ST_SetSRID(ext.ST_MakePoint(65.5+g*0.01,44.8+g*0.01),4326)::ext.geography FROM generate_series(1,3)g;
INSERT INTO org.department(id,site_id,code,name,kind) SELECT g,((g-1)/10)+1,'DEP-'||lpad(g::text,2,'0'),(ARRAY['Терапевтическое','Хирургическое','Кардиологическое','Неврологическое','Педиатрическое','Реабилитационное','Диагностическое','Лабораторное','Интенсивной терапии','Приёмное'])[((g-1)%10)+1]||' / корпус '||(((g-1)/10)+1),CASE WHEN g%10 IN(7,8) THEN 'diagnostic' ELSE 'clinical' END FROM generate_series(1,30)g;
INSERT INTO org.room(id,department_id,code,name,kind,floor_number) SELECT g,((g-1)/4)+1,'WARD-'||g,'Палата '||g,'ward',((g-1)%4)+1 FROM generate_series(1,120)g;
INSERT INTO org.room(id,department_id,code,name,kind,floor_number) SELECT 120+g,((g-1)%30)+1,'CONS-'||g,'Кабинет '||g,'consultation',((g-1)%4)+1 FROM generate_series(1,240)g;
INSERT INTO org.bed SELECT g,((g-1)/4)+1,'BED-'||lpad(g::text,4,'0'),true,CASE WHEN g%20=0 THEN 'icu' WHEN g%17=0 THEN 'isolation' WHEN g%11=0 THEN 'pediatric' ELSE 'standard' END FROM generate_series(1,480)g;
INSERT INTO org.staff SELECT g,'EMP-'||lpad(g::text,5,'0'),'Сотрудник '||lpad(g::text,4,'0'),CASE WHEN g<=240 THEN 'physician' WHEN g<=480 THEN 'nurse' WHEN g<=540 THEN 'technician' WHEN g<=570 THEN 'pharmacist' ELSE 'administrator' END,51+((g-1)%10),true FROM generate_series(1,600)g;
INSERT INTO org.staff_department SELECT g,((g-1)%30)+1,daterange('2023-01-01',NULL,'[)'),true FROM generate_series(1,600)g;
INSERT INTO org.credential(staff_id,credential_type,identifier,valid_during,issuer) SELECT g,'DEMO-CREDENTIAL','SYNTH-CRED-'||g,daterange('2023-01-01','2028-01-01','[)'),'Учебный реестр' FROM generate_series(1,600)g;
INSERT INTO org.device(id,department_id,asset_tag,name,modality,serial_number,next_maintenance_on) SELECT g,((g-1)%30)+1,'ASSET-'||g,'Учебный прибор '||g,(ARRAY['CT','MR','US','DX'])[1+(g-1)%4],'SYNTH-SERIAL-'||g,DATE '2027-01-01'+(g%90) FROM generate_series(1,90)g;
INSERT INTO mpi.patient(id,mrn,family_name,given_name,birth_date,administrative_gender,created_at,updated_at) SELECT g,'DEMO-'||lpad(g::text,8,'0'),'Пациент','Синтетический '||lpad(g::text,6,'0'),DATE '1940-01-01'+((g*97)%27000)::int,CASE WHEN g%2=0 THEN 'female' ELSE 'male' END,TIMESTAMPTZ '2023-01-01 00:00+05',TIMESTAMPTZ '2023-01-01 00:00+05' FROM generate_series(1,120002)g;
INSERT INTO mpi.identifier(patient_id,system_uri,value) SELECT id,'urn:demo:hospital:synthetic-id','SYNTH-'||lpad(id::text,10,'0') FROM mpi.patient;
INSERT INTO mpi.address(patient_id,use_code,country_code,city,line_text,location,valid_during) SELECT id,'home','KZ',(ARRAY['Кызылорда','Астана','Алматы','Шымкент','Караганда'])[1+(id%5)::int],'Учебный адрес '||id,ext.ST_SetSRID(ext.ST_MakePoint(65.2+(id%100)*0.006,44.6+((id/100)%100)*0.006),4326)::ext.geography,daterange('2023-01-01',NULL,'[)') FROM mpi.patient;
INSERT INTO mpi.contact(patient_id,system,value,use_code,rank) SELECT id,'email','patient-'||id||'@hospital.example.invalid','home',1 FROM mpi.patient;
INSERT INTO mpi.related_person(patient_id,display_name,relationship,contact_text,is_emergency_contact) SELECT id,'Представитель '||id,'synthetic-relative','not-a-real-contact',true FROM mpi.patient WHERE id<=30000;
INSERT INTO mpi.consent(patient_id,scope,status,valid_during,recorded_at,recorded_by,document_reference) SELECT id,'treatment','active',tstzrange('2023-01-01 00:00+05',NULL,'[)'),'2023-01-01 00:00+05',571,'urn:demo:consent:'||id FROM mpi.patient;
INSERT INTO mpi.merge_history(source_patient_id,target_patient_id,merged_at,merged_by,reason) VALUES(120001,119999,'2026-10-01 12:00+05',571,'Учебный пример деактивации дубликата; источник без клинической истории');
INSERT INTO iam.application_user VALUES(1,'hospital_demo_clinician',1,'Демо: врач',true),(2,'hospital_demo_registrar',571,'Демо: регистратор',true),(3,'hospital_demo_billing',572,'Демо: расчёты',true),(4,'hospital_owner',600,'Служебный владелец',true);
INSERT INTO iam.business_role VALUES('clinician','Врач'),('registrar','Регистратор'),('billing','Расчёты'),('administrator','Администратор');
