INSERT INTO iam.access_grant(user_id,patient_id,purpose,valid_during,granted_by,reason) SELECT u,g,CASE u WHEN 1 THEN 'treatment' WHEN 2 THEN 'registration' ELSE 'billing' END,tstzrange('2023-01-01 00:00+05','2030-01-01 00:00+05','[)'),4,'Явное учебное назначение доступа' FROM generate_series(1,3)u CROSS JOIN generate_series(1,100)g;
INSERT INTO iam.break_glass(user_id,patient_id,reason,valid_during,approved_by,reviewed_at) VALUES(1,101,'Истёкший учебный экстренный доступ',tstzrange('2026-10-01 10:00+05','2026-10-01 10:30+05','[)'),4,'2026-10-01 12:00+05');
INSERT INTO ehr.encounter(id,patient_id,type_code,department_id,attending_staff_id,status,started_at,ended_at,chief_complaint,created_at,updated_at) SELECT g,((g-1)%120000)+1,CASE WHEN g%15=0 THEN 'emergency' ELSE 'outpatient' END,((g-1)%30)+1,((g-1)%240)+1,'finished',t,t+INTERVAL '30 minutes','Синтетический учебный приём',t,t+INTERVAL '30 minutes' FROM generate_series(1,300000)g CROSS JOIN LATERAL(SELECT TIMESTAMPTZ '2024-01-01 08:00+05'+((g-1)/600)*INTERVAL '1 day'+((g-1)%600)*INTERVAL '1 minute' t)x;
INSERT INTO ehr.encounter(id,patient_id,type_code,department_id,attending_staff_id,status,started_at,ended_at,chief_complaint,created_at,updated_at) SELECT 300000+g,90000+g,'inpatient',(((g-1)%480)/16)+1,(((g-1)%480)/16)+1,CASE WHEN g>29700 THEN 'in-progress' ELSE 'finished' END,t,CASE WHEN g<=29700 THEN t+INTERVAL '4 days' END,'Учебная госпитализация',t,t FROM generate_series(1,30000)g CROSS JOIN LATERAL(SELECT CASE WHEN g>29700 THEN TIMESTAMPTZ '2026-10-17 10:00+05' ELSE TIMESTAMPTZ '2024-01-01 10:00+05'+((g-1)/480)*INTERVAL '7 days' END t)x;
INSERT INTO ehr.encounter_participant SELECT id,attending_staff_id,'attending',tstzrange(started_at,ended_at,'[)') FROM ehr.encounter;
INSERT INTO ehr.condition(patient_id,encounter_id,concept_id,clinical_status,verification_status,onset_at,rank,recorded_by) SELECT patient_id,id,1+((id-1)%40)::int,CASE WHEN id%4=0 THEN 'active' ELSE 'resolved' END,'confirmed',started_at,1,attending_staff_id FROM ehr.encounter WHERE id<=180000;
INSERT INTO ehr.allergy(patient_id,substance_concept_id,clinical_status,verification_status,criticality,reaction_text,recorded_at,recorded_by) SELECT g,41+((g-1)%10)::int,'active','unconfirmed','unable-to-assess','Учебная запись; не клиническое заключение','2023-01-01 00:00+05',1 FROM generate_series(1,15000)g;
INSERT INTO ehr.observation(patient_id,encounter_id,test_id,observed_at,status,value_numeric,unit_code,recorded_by) SELECT e.patient_id,e.id,k,e.started_at+k*INTERVAL '1 minute','final',CASE k WHEN 1 THEN 60+(e.id%35) WHEN 2 THEN 36.0+(e.id%15)*0.1 WHEN 3 THEN 100+(e.id%45) WHEN 4 THEN 95+(e.id%6) END,(ARRAY['1/min','Cel','mmHg','%'])[k],e.attending_staff_id FROM ehr.encounter e CROSS JOIN generate_series(1,4)k;
INSERT INTO ehr.procedure(patient_id,encounter_id,service_id,status,performed_period,performer_id,outcome_text) SELECT patient_id,id,4,'completed',tstzrange(started_at+INTERVAL '5 minutes',started_at+INTERVAL '20 minutes','[)'),attending_staff_id,'Учебная процедура выполнена' FROM ehr.encounter WHERE id<=40000;
INSERT INTO ehr.clinical_note(id,patient_id,encounter_id,note_type,author_id,created_at) SELECT id,patient_id,id,CASE WHEN type_code='inpatient' AND status='finished' THEN 'discharge' ELSE 'consultation' END,attending_staff_id,started_at+INTERVAL '10 minutes' FROM ehr.encounter;
INSERT INTO ehr.note_version(note_id,version,body,created_at,author_id,signed_at,signed_by) SELECT id,1,'СИНТЕТИЧЕСКИЕ ДАННЫЕ. Учебная клиническая запись эпизода '||id||'. Не использовать для лечения.',created_at,author_id,created_at+INTERVAL '5 minutes',author_id FROM ehr.clinical_note;
INSERT INTO ehr.care_plan(id,patient_id,encounter_id,status,title,valid_during,author_id) SELECT id,patient_id,id,'completed','Учебный план наблюдения',tstzrange(started_at,started_at+INTERVAL '30 days','[)'),attending_staff_id FROM ehr.encounter WHERE id<=20000;
INSERT INTO ehr.care_plan_activity(care_plan_id,service_id,status,scheduled_at,assigned_staff_id) SELECT id,1,'completed',lower(valid_during)+INTERVAL '7 days',author_id FROM ehr.care_plan;
INSERT INTO ehr.document(patient_id,encounter_id,document_type,storage_uri,media_type,size_bytes,sha256,created_at,author_id) SELECT patient_id,id,'demo-metadata-only','urn:demo:document:'||id,'text/plain',100,ext.digest('synthetic-document-'||id,'sha256'),started_at,attending_staff_id FROM ehr.encounter WHERE id<=10000;
INSERT INTO ehr.death_record VALUES(120002,NULL,'2026-01-01 12:00+05',1,1,'SYNTH-DEATH-1');
INSERT INTO ehr.immunization(patient_id,encounter_id,vaccine_concept_id,occurred_at,status,lot_number,performer_id) SELECT patient_id,id,61,started_at+INTERVAL '10 minutes','completed','DEMO-VACCINE-LOT',attending_staff_id FROM ehr.encounter WHERE id<=10000;
INSERT INTO adt.admission(id,patient_id,encounter_id,admission_number,admitted_at,discharged_at,admission_source) SELECT id-300000,patient_id,id,'ADM-'||id,started_at,ended_at,CASE WHEN id%2=0 THEN 'referral' ELSE 'emergency' END FROM ehr.encounter WHERE type_code='inpatient';
INSERT INTO adt.bed_stay(admission_id,patient_id,bed_id,occupied_during) SELECT id,patient_id,((id-1)%480)+1,tstzrange(admitted_at,discharged_at,'[)') FROM adt.admission;
INSERT INTO adt.discharge SELECT id,patient_id,discharged_at,'home',encounter_id,((id-1)%30)+1 FROM adt.admission WHERE discharged_at IS NOT NULL;
INSERT INTO scheduling.schedule(id,staff_id,department_id,valid_during) SELECT g,g,((g-1)%30)+1,daterange('2024-01-01','2028-01-01','[)') FROM generate_series(1,240)g;
INSERT INTO scheduling.slot(id,schedule_id,staff_id,department_id,room_id,slot_period,status) SELECT g,((g-1)%240)+1,((g-1)%240)+1,((g-1)%30)+1,121+((g-1)%240),tstzrange(t,t+INTERVAL '20 minutes','[)'),'busy' FROM generate_series(1,120000)g CROSS JOIN LATERAL(SELECT TIMESTAMPTZ '2026-10-19 08:00+05'+((g-1)/240/20)*INTERVAL '1 day'+(((g-1)/240)%20)*INTERVAL '20 minutes' t)x;
INSERT INTO scheduling.appointment(id,patient_id,slot_id,service_id,status,created_at,reason_text) SELECT g,g,g,1,'booked','2026-10-01 10:00+05','Учебная запись на приём' FROM generate_series(1,120000)g;
INSERT INTO scheduling.appointment_participant SELECT a.id,s.staff_id,'accepted' FROM scheduling.appointment a JOIN scheduling.slot s ON s.id=a.slot_id;
INSERT INTO lab.service_request(id,patient_id,encounter_id,service_id,panel_id,ordered_by,ordered_at,priority,status) SELECT id,patient_id,id,2,1,attending_staff_id,started_at+INTERVAL '5 minutes',CASE WHEN id%20=0 THEN 'urgent' ELSE 'routine' END,'completed' FROM ehr.encounter WHERE id<=120000;
INSERT INTO lab.specimen(id,patient_id,accession_number,type_code,collected_at,received_at,status,collected_by) SELECT id,patient_id,'SYNTH-SPEC-'||id,'demo-material',ordered_at+INTERVAL '10 minutes',ordered_at+INTERVAL '20 minutes','available',241+(id%240) FROM lab.service_request;
INSERT INTO lab.request_specimen SELECT id,id,patient_id FROM lab.service_request;
INSERT INTO lab.diagnostic_report(id,patient_id,request_id,status,issued_at,verified_by,conclusion_text) SELECT id,patient_id,id,'final',ordered_at+INTERVAL '4 hours',481+(id%60),'Учебный результат; медицинская интерпретация отсутствует' FROM lab.service_request;
INSERT INTO lab.result(id,patient_id,specimen_id,test_id,measured_at,status,value_numeric,unit_code,interpretation,analyzer_id) SELECT (s.id-1)*3+k,s.patient_id,s.id,4+k,s.received_at+INTERVAL '1 hour','final',round((10+(s.id%100)*0.15+k)::numeric,2),'AU','not-applicable',1+(s.id%90) FROM lab.specimen s CROSS JOIN generate_series(1,3)k;
INSERT INTO lab.report_result SELECT specimen_id,id,patient_id FROM lab.result;
INSERT INTO imaging.imaging_order(id,patient_id,encounter_id,service_id,requested_at,requested_by,status) SELECT id,patient_id,id,3,started_at,attending_staff_id,'completed' FROM ehr.encounter WHERE id<=40000;
INSERT INTO imaging.study(id,patient_id,order_id,study_instance_uid,accession_number,modality,started_at,status,device_id,report_text) SELECT id,patient_id,id,'2.25.202610190000'||id,'IMG-'||id,(ARRAY['CT','MR','US','DX'])[1+(id%4)::int],requested_at+INTERVAL '1 hour','available',1+(id%90),'Синтетическое исследование; изображений нет' FROM imaging.imaging_order;
INSERT INTO imaging.series(study_id,series_instance_uid,series_number,instance_count,storage_uri) SELECT id,'2.25.202610190001'||id,1,0,'urn:demo:dicom-metadata-only:'||id FROM imaging.study;
INSERT INTO inventory.supplier SELECT g,'SUP-'||g,'Учебный поставщик '||g,true FROM generate_series(1,10)g;
