INSERT INTO inventory.lot SELECT id,id,'SYNTH-LOT-'||id,'2028-12-31',1+(id%10),'2023-01-01' FROM inventory.item;
INSERT INTO inventory.purchase_order SELECT g,'PO-'||g,1+(g%10),'received','2023-01-01 10:00+05','KZT' FROM generate_series(1,10)g;
INSERT INTO inventory.purchase_order_line SELECT 1+(id%10),id,id,1000000,100 FROM inventory.item;
INSERT INTO inventory.stock_movement(location_id,lot_id,quantity_delta,movement_type,occurred_at,recorded_by,reason) SELECT 1,id,1000000,'receipt','2023-01-01 10:00+05',541,'Начальный учебный приход' FROM inventory.lot;
INSERT INTO pharmacy.medication_order(id,patient_id,encounter_id,medication_id,ordered_by,ordered_at,status,route_code,instructions,valid_during) SELECT id,patient_id,id,1+((id-1)%40)::int,attending_staff_id,started_at,'completed','demo-route','Только симуляция. Не является назначением или рекомендацией.',tstzrange(started_at,started_at+INTERVAL '7 days','[)') FROM ehr.encounter WHERE id<=90000;
INSERT INTO pharmacy.dispense(id,patient_id,order_id,medication_id,item_id,lot_id,location_id,quantity,dispensed_at,dispensed_by) SELECT id,patient_id,id,medication_id,medication_id,medication_id,1,1,ordered_at+INTERVAL '1 hour',541+(id%30) FROM pharmacy.medication_order;
INSERT INTO pharmacy.administration(patient_id,order_id,dispense_id,administered_at,status,quantity,unit_code,performed_by,note) SELECT patient_id,order_id,id,dispensed_at+INTERVAL '1 hour','completed',1,'each',241+(id%240),'Симуляция; не руководство по применению' FROM pharmacy.dispense;
INSERT INTO pharmacy.medication_reconciliation(patient_id,encounter_id,reconciled_at,reconciled_by,status,note) SELECT patient_id,id,started_at,attending_staff_id,'completed','Учебная сверка назначений' FROM ehr.encounter WHERE id<=30000;
INSERT INTO billing.payer VALUES(1,'PUBLIC-DEMO','Учебный государственный плательщик','public'),(2,'PRIVATE-DEMO','Учебная страховая организация','private'),(3,'SELF-DEMO','Личная оплата','self-pay');
INSERT INTO billing.coverage(id,patient_id,payer_id,policy_number,valid_during,priority) SELECT id,id,1+((id-1)%3),'SYNTH-POLICY-'||id,daterange('2023-01-01','2028-01-01','[)'),1 FROM mpi.patient;
INSERT INTO billing.tariff(service_id,payer_id,valid_during,amount,currency_code) SELECT s.id,p.id,daterange('2023-01-01','2028-01-01','[)'),CASE s.id WHEN 1 THEN 5000 WHEN 2 THEN 2500 WHEN 3 THEN 15000 WHEN 4 THEN 7000 ELSE 20000 END,'KZT' FROM ref.service s CROSS JOIN billing.payer p;
INSERT INTO billing.invoice(id,patient_id,encounter_id,invoice_number,payer_id,coverage_id,issued_at,due_at,status,currency_code) SELECT id,patient_id,id,'INV-'||lpad(id::text,8,'0'),1+((patient_id-1)%3),patient_id,started_at+INTERVAL '1 day',started_at+INTERVAL '31 days','draft','KZT' FROM ehr.encounter WHERE id<=180000;
INSERT INTO billing.invoice_line(invoice_id,line_no,service_id,quantity,unit_price) SELECT id,1,1,1,5000+(id%20)*250 FROM billing.invoice;
INSERT INTO billing.invoice_line(invoice_id,line_no,service_id,quantity,unit_price) SELECT id,2,2,1,2500 FROM billing.invoice;
INSERT INTO billing.payment(id,patient_id,payer_id,received_at,amount,currency_code,method,external_reference) SELECT id,patient_id,payer_id,issued_at+INTERVAL '10 days',7500+(id%20)*250,'KZT',CASE WHEN id%2=0 THEN 'card' ELSE 'transfer' END,'SYNTH-TXN-'||id FROM billing.invoice WHERE id<=150000;
INSERT INTO billing.payment_allocation(payment_id,invoice_id,patient_id,amount,allocated_at) SELECT id,id,patient_id,amount,received_at FROM billing.payment;
INSERT INTO billing.claim(patient_id,invoice_id,payer_id,claim_number,status,submitted_at,adjudicated_at) SELECT patient_id,id,payer_id,'CLAIM-'||id,CASE WHEN id<=150000 THEN 'accepted' ELSE 'submitted' END,issued_at+INTERVAL '1 day',CASE WHEN id<=150000 THEN issued_at+INTERVAL '9 days' END FROM billing.invoice;
INSERT INTO quality.incident(patient_id,encounter_id,department_id,occurred_at,reported_at,reported_by,category,severity,status,description) SELECT patient_id,id,department_id,started_at,started_at+INTERVAL '1 hour',attending_staff_id,'demo-process-deviation','near-miss','closed','Синтетический учебный инцидент' FROM ehr.encounter WHERE id<=1000;
INSERT INTO quality.infection_case(patient_id,encounter_id,onset_at,classification,reported_by) SELECT patient_id,id,started_at+INTERVAL '1 day','excluded',attending_staff_id FROM ehr.encounter WHERE id BETWEEN 300001 AND 300300;
INSERT INTO quality.patient_feedback(patient_id,encounter_id,submitted_at,rating,comment_text) SELECT patient_id,id,ended_at+INTERVAL '1 day',1+(id%5),'Синтетическая оценка' FROM ehr.encounter WHERE id<=20000;
INSERT INTO integration.outbox(aggregate_type,aggregate_id,event_type,payload,created_at,published_at) SELECT 'Patient',public_id::text,'demo.patient.registered',jsonb_build_object('resourceType','Patient','id',public_id,'synthetic',true),created_at,CASE WHEN id%10<>0 THEN created_at+INTERVAL '1 minute' END FROM mpi.patient WHERE id<=2000;
INSERT INTO integration.inbox SELECT 'demo-lis','MSG-'||g,'2026-10-01 10:00+05',ext.digest('SYNTH-MESSAGE-'||g,'sha256'),'processed','2026-10-01 10:01+05',NULL FROM generate_series(1,2000)g;
INSERT INTO integration.external_identifier(resource_type,internal_public_id,system_uri,external_id) SELECT 'Patient',public_id,'urn:demo:external-mpi','EXT-'||id FROM mpi.patient WHERE id<=2000;
INSERT INTO integration.export_job(requested_by,purpose,requested_at,status,filter_json,output_uri,completed_at) VALUES(4,'Учебный обезличенный экспорт','2026-10-01 12:00+05','completed','{"synthetic":true,"aggregate_only":true}','urn:demo:export:1','2026-10-01 12:01+05');
INSERT INTO audit.access_event(actor,patient_id,purpose,action,request_id,reason) SELECT 'hospital_demo_clinician',g,'treatment','read',gen_random_uuid(),'Синтетическое событие доступа, создано генератором' FROM generate_series(1,100)g;
INSERT INTO ops.schema_migration VALUES('05',clock_timestamp(),'Deterministic synthetic dataset; no real patients or medical recommendations');
