\set ON_ERROR_STOP on
\timing on
SET ROLE hospital_owner;
SET search_path=pg_catalog,ext,public;
SET TIME ZONE 'Asia/Qyzylorda';
BEGIN;
UPDATE mpi.patient SET active=false WHERE id=120001;
UPDATE mpi.patient SET deceased_at='2026-01-01 12:00+05' WHERE id=120002;
UPDATE billing.invoice SET status='issued';
-- Explicit IDs are used to make the dataset reproducible. Advance every identity sequence.
DO $$DECLARE r record; mx bigint; BEGIN FOR r IN SELECT n.nspname,c.relname,a.attname,pg_get_serial_sequence(format('%I.%I',n.nspname,c.relname),a.attname) seq FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid WHERE c.relkind IN('r','p') AND a.attidentity<>'' AND n.nspname NOT IN('ext','pg_catalog','information_schema') AND NOT c.relispartition LOOP EXECUTE format('SELECT max(%I) FROM %I.%I',r.attname,r.nspname,r.relname) INTO mx; PERFORM setval(r.seq::regclass,coalesce(mx,1),mx IS NOT NULL); END LOOP; END$$;
COMMIT;
